import {
  RICH_CONTENT_DEFAULT_PATH,
  REPOS_SEARCH_PATH,
  TopRepos,
  useRichContent,
} from '@github-ui/global-navigation/menu/dynamic-content/dynamic-side-panel-content'
import {GlobalNavAnalyticsProvider} from '@github-ui/global-navigation/analytics'
import {NavList, Spinner} from '@primer/react'
import styles from './DashboardRepositories.module.css'

// initially show 10 items
const INITIAL_ITEMS_PER_PAGE = 10
// then load an additional 90 items
const ITEMS_PER_PAGE = 90
// only allow the show more button to be pressed once
const MAX_PAGES = 2

export const DashboardRepositories = () => {
  const {data, isError, isLoading} = useRichContent({
    richContentUrl: RICH_CONTENT_DEFAULT_PATH,
    itemsPerPage: ITEMS_PER_PAGE,
    additionalRepositoryParams: {
      initialItemsPerPage: INITIAL_ITEMS_PER_PAGE,
      maxPages: MAX_PAGES,
    },
  })

  if (!isError && isLoading) {
    return (
      <div
        className={`d-flex flex-justify-center width-full tmp-my-3 ${styles.delayLoader}`}
        data-testid="dashboard-repositories-loading"
        aria-live="polite"
        aria-busy="true"
      >
        <Spinner size="small" />
      </div>
    )
  }

  return (
    <GlobalNavAnalyticsProvider category="DASHBOARD_REPOSITORIES">
      <NavList data-testid="dashboard-repositories">
        {isError ? (
          <NavList.Item data-testid="dashboard-repositories-error">Error loading repositories</NavList.Item>
        ) : !data?.repositories || data.repositories.length === 0 ? (
          <NavList.Item data-testid="dashboard-repositories-empty">No repositories found</NavList.Item>
        ) : (
          <TopRepos
            initialItems={data.repositories}
            searchUrl={REPOS_SEARCH_PATH}
            itemsPerPage={ITEMS_PER_PAGE}
            initialItemsPerPage={INITIAL_ITEMS_PER_PAGE}
            maxPages={MAX_PAGES}
          />
        )}
      </NavList>
    </GlobalNavAnalyticsProvider>
  )
}
